"""Tests for depcycle CLI commands."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from depcycle.cli import DepCycleCLI


def test_cli_validate_project_path(tmp_path: Path) -> None:
    non_existent = tmp_path / "missing"
    with pytest.raises(SystemExit) as exc_info:
        DepCycleCLI._validate_project_path(non_existent)
    assert exc_info.value.code == 1

    file_path = tmp_path / "file.txt"
    file_path.write_text("hello", encoding="utf-8")
    with pytest.raises(SystemExit) as exc_info:
        DepCycleCLI._validate_project_path(file_path)
    assert exc_info.value.code == 1


def test_cli_analyze_stdout(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    (tmp_path / "app.py").write_text("import sys\n", encoding="utf-8")

    DepCycleCLI.main(["analyze", str(tmp_path), "-o", "-"])
    captured = capsys.readouterr()
    assert "<!DOCTYPE html>" in captured.out
    assert "Analyzing project:" in captured.err


def test_cli_analyze_default_output_filename(
    tmp_path: Path, capsys: pytest.CaptureFixture[str], monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "app.py").write_text("import sys\n", encoding="utf-8")

    # When -o is omitted, output_path becomes dependencies.<format>
    DepCycleCLI.main(["analyze", str(tmp_path), "-f", "dot"])
    captured = capsys.readouterr()
    assert (tmp_path / "dependencies.dot").is_file()
    assert "✓ DOT output saved to: dependencies.dot" in captured.err


